"""Rich terminal notifier with a bounded, deterministic anti-spam registry.The spam problem, precisely---------------------------A live odds feed re-quotes the same selection several times per second. Withouta debouncer, one genuinely useful recommendation on "Arsenal moneyline" becomesa hundred identical alerts as the price drifts between 2.10 and 2.11. The userstops reading, and a firewall that is not read is not a firewall.The debounce key therefore **excludes price**. Identity is``(bookmaker, sport, selection, action)``, so a re-quote maps to the same key.The channel re-opens on exactly three conditions:#. **First sighting** of the key.#. **Material change in expected value.** Measured as an absolute shift in edge   per unit staked, not as a change in odds. A price moving 2.10 to 2.11 shifts   the edge by well under the threshold; a price moving 2.10 to 2.40 shifts it   materially and is genuinely new information.#. **TTL expiry.** After the TTL the recommendation is re-surfaced even if   unchanged, because a still-live opportunity the user has not acted on is   worth one reminder.Memory safety-------------The registry is keyed on unbounded user data inside a long-running process, soan uncapped dictionary is a guaranteed leak. Capacity is fixed and eviction isstrict LRU. Under sustained load the registry occupies a constant, known numberof entries regardless of how many distinct selections stream past.Timekeeping-----------Intervals are measured on ``time.monotonic`` when no clock is injected, so anNTP step cannot make a TTL appear expired or eternal. When a ``now`` isinjected the wall-clock delta is used instead, which makes every suppressiondecision exactly reproducible in tests."""from __future__ import annotationsimport asyncioimport contextlibimport sysimport timefrom collections import OrderedDict, dequefrom collections.abc import Sequencefrom dataclasses import dataclassfrom datetime import datetimefrom typing import Final, Selfimport structlogfrom pydantic import BaseModel, ConfigDict, Field, model_validatorfrom rich import boxfrom rich.console import Consolefrom rich.panel import Panelfrom rich.table import Tablefrom rich.text import Textfrom betdoc.application.ports.notifiers import (    DebounceDecision,    DebounceReason,    NotificationChannel,    NotificationDebouncer,    NotifierUnavailableError,    RecommendationNotifier,    recommendation_dedupe_key,)from betdoc.domain.intelligence.account_models import utc_nowfrom betdoc.domain.intelligence.advisor_models import (    ForecastVerdict,    SessionForecast,    TwinRecommendation,    VolatilityRegime,)__all__ = [    "AntiSpamConfig",    "AntiSpamRegistry",    "RichConsoleNotifier",    "format_inr",]_log: Final[structlog.stdlib.BoundLogger] = structlog.get_logger(    component="adapters.notifiers.console")_PAISE_PER_RUPEE: Final[int] = 100def format_inr(paise: int) -> str:    """Render integer paise as INR. Never converts through a float."""    sign = "-" if paise < 0 else ""    magnitude = abs(paise)    rupees, remainder = divmod(magnitude, _PAISE_PER_RUPEE)    return f"{sign}\u20b9{rupees:,}.{remainder:02d}"def _edge_per_unit(recommendation: TwinRecommendation) -> float | None:    """Edge per unit staked, the quantity the debouncer compares.    Preferred source is ``news_adjusted_probability * target_odds - 1``, which    is the post-news edge the Twin actually sized on. Falls back to    ``expected_value / stake``, which is arithmetically the same figure when    both are present, and returns ``None`` only for a refusal carrying neither.    """    if recommendation.news_adjusted_probability is not None:        return recommendation.news_adjusted_probability * recommendation.target_odds - 1.0    if recommendation.suggested_stake_paise > 0:        return recommendation.expected_value_paise / recommendation.suggested_stake_paise    return None@dataclass(slots=True)class _RegistryEntry:    """Last delivery for one debounce key."""    notified_at: datetime    notified_monotonic: float    edge_per_unit: float | None    stake_paise: int    delivery_count: intclass AntiSpamConfig(BaseModel):    """Debounce policy. Every threshold is explicit and tunable."""    model_config = ConfigDict(frozen=True, extra="forbid", validate_default=True)    ttl_seconds: float = Field(        default=300.0,        gt=0.0,        le=86_400.0,        description="Re-surface an unchanged recommendation after this long.",    )    edge_shift_threshold: float = Field(        default=0.02,        gt=0.0,        le=1.0,        description=(            "Absolute change in edge per unit staked that re-opens the channel. "            "0.02 means two percentage points of edge. Compared on edge rather "            "than on odds so a cosmetic price tick cannot trigger an alert."        ),    )    max_entries: int = Field(        default=4_096,        ge=16,        le=1_000_000,        description=(            "Hard capacity with strict LRU eviction. Fixed because the key "            "space is unbounded and this process is long-running."        ),    )    max_per_minute: int = Field(        default=30,        ge=1,        le=10_000,        description="Global delivery ceiling. The backstop behind the debouncer.",    )    suppress_expired_recommendations: bool = Field(        default=True,        description="Never surface advice that has already passed its own expiry.",    )    @model_validator(mode="after")    def _thresholds_are_coherent(self) -> Self:        if self.max_entries < self.max_per_minute:            msg = "max_entries must be at least max_per_minute to avoid thrashing"            raise ValueError(msg)        return selfclass AntiSpamRegistry(NotificationDebouncer):    """Bounded, LRU, monotonic-safe implementation of the debounce port.    Not thread-safe by design: it is driven from a single event loop and adding    a lock to the hot path of every recommendation would cost more than it    protects. If it is ever shared across loops, wrap it rather than mutating    it here.    """    __slots__ = (        "_config",        "_critical_reasons",        "_deliveries",        "_entries",        "_evictions",        "_suppressions",    )    def __init__(self, config: AntiSpamConfig | None = None) -> None:        self._config = config or AntiSpamConfig()        self._entries: OrderedDict[str, _RegistryEntry] = OrderedDict()        self._deliveries: deque[float] = deque()        self._critical_reasons = RecommendationNotifier.critical_rejections()        self._suppressions = 0        self._evictions = 0    @property    def tracked_keys(self) -> int:        return len(self._entries)    @property    def suppression_count(self) -> int:        """Total suppressions. An unmeasured gate is an unverified gate."""        return self._suppressions    @property    def eviction_count(self) -> int:        return self._evictions    def _elapsed_seconds(self, entry: _RegistryEntry, now: datetime | None) -> float:        """Interval since last delivery, monotonic unless a clock is injected."""        if now is None:            return max(time.monotonic() - entry.notified_monotonic, 0.0)        return max((now - entry.notified_at).total_seconds(), 0.0)    def _rate_limited(self, now: datetime | None) -> bool:        """Sliding one-minute window over deliveries, on the monotonic clock."""        if now is not None:            return False        cutoff = time.monotonic() - 60.0        while self._deliveries and self._deliveries[0] < cutoff:            self._deliveries.popleft()        return len(self._deliveries) >= self._config.max_per_minute    def evaluate(        self, recommendation: TwinRecommendation, *, now: datetime | None = None    ) -> DebounceDecision:        """Decide whether this recommendation may be delivered.        Gate order is deliberate. The critical override runs first, before the        rate limit, so a breached daily loss limit is never swallowed by a        flood of routine alerts that happened to arrive in the same minute.        """        key = recommendation_dedupe_key(recommendation)        current_edge = _edge_per_unit(recommendation)        moment = now or utc_now()        reason = recommendation.rejection_reason        if reason is not None and reason in self._critical_reasons:            return DebounceDecision(                allow=True,                reason=DebounceReason.CRITICAL_OVERRIDE,                dedupe_key=key,                current_edge_per_unit=current_edge,                detail=f"{reason.value} always bypasses the debouncer",            )        if self._config.suppress_expired_recommendations and recommendation.is_expired(now=moment):            self._suppressions += 1            return DebounceDecision(                allow=False,                reason=DebounceReason.SUPPRESSED_EXPIRED_RECOMMENDATION,                dedupe_key=key,                current_edge_per_unit=current_edge,                detail="recommendation is past its own validity window",            )        entry = self._entries.get(key)        if entry is None:            if self._rate_limited(now):                self._suppressions += 1                return DebounceDecision(                    allow=False,                    reason=DebounceReason.SUPPRESSED_RATE_LIMIT,                    dedupe_key=key,                    current_edge_per_unit=current_edge,                    detail=f"global ceiling of {self._config.max_per_minute}/min reached",                )            return DebounceDecision(                allow=True,                reason=DebounceReason.FIRST_SEEN,                dedupe_key=key,                current_edge_per_unit=current_edge,                detail="no prior delivery for this selection",            )        self._entries.move_to_end(key)        elapsed = self._elapsed_seconds(entry, now)        shift = (            abs(current_edge - entry.edge_per_unit)            if current_edge is not None and entry.edge_per_unit is not None            else None        )        base = {            "dedupe_key": key,            "previous_notified_at": entry.notified_at,            "previous_edge_per_unit": entry.edge_per_unit,            "current_edge_per_unit": current_edge,            "edge_shift_absolute": shift,            "seconds_since_previous": elapsed,        }        if elapsed >= self._config.ttl_seconds:            allow_reason = DebounceReason.TTL_EXPIRED            detail = (                f"{elapsed:.0f}s since last alert exceeds the {self._config.ttl_seconds:.0f}s TTL"            )        elif shift is not None and shift >= self._config.edge_shift_threshold:            allow_reason = DebounceReason.EV_SHIFT_EXCEEDED            detail = (                f"edge moved {shift:+.2%}, above the "                f"{self._config.edge_shift_threshold:.2%} threshold"            )        else:            self._suppressions += 1            return DebounceDecision(                allow=False,                reason=DebounceReason.SUPPRESSED_DUPLICATE,                detail=(                    f"same selection alerted {elapsed:.0f}s ago; edge shift "                    f"{shift:+.2%} is immaterial"                    if shift is not None                    else f"same selection alerted {elapsed:.0f}s ago"                ),                **base,  # type: ignore[arg-type]            )        if self._rate_limited(now):            self._suppressions += 1            return DebounceDecision(                allow=False,                reason=DebounceReason.SUPPRESSED_RATE_LIMIT,                detail=f"global ceiling of {self._config.max_per_minute}/min reached",                **base,  # type: ignore[arg-type]            )        return DebounceDecision(            allow=True,            reason=allow_reason,            detail=detail,            **base,  # type: ignore[arg-type]        )    def record_delivery(        self, recommendation: TwinRecommendation, *, now: datetime | None = None    ) -> None:        """Register a delivery. Called only after the channel succeeded.        Recording after delivery rather than after the decision means a failed        send does not suppress its own retry, which would silently lose the        alert entirely.        """        key = recommendation_dedupe_key(recommendation)        previous = self._entries.get(key)        self._entries[key] = _RegistryEntry(            notified_at=now or utc_now(),            notified_monotonic=time.monotonic(),            edge_per_unit=_edge_per_unit(recommendation),            stake_paise=recommendation.suggested_stake_paise,            delivery_count=(previous.delivery_count + 1) if previous else 1,        )        self._entries.move_to_end(key)        self._deliveries.append(time.monotonic())        self._evict_if_over_capacity()    def _evict_if_over_capacity(self) -> None:        """Strict LRU eviction to a fixed ceiling."""        while len(self._entries) > self._config.max_entries:            self._entries.popitem(last=False)            self._evictions += 1    def prune(self, *, now: datetime | None = None) -> int:        """Drop entries older than twice the TTL. Returns the number removed.        Two TTLs rather than one, so an entry is never pruned while it could        still be suppressing a duplicate. Pruning is an optimisation; the LRU        cap is the actual memory guarantee.        """        horizon = self._config.ttl_seconds * 2.0        expired = [            key            for key, entry in self._entries.items()            if self._elapsed_seconds(entry, now) > horizon        ]        for key in expired:            del self._entries[key]        return len(expired)    def snapshot(self) -> dict[str, int]:        return {            "tracked_keys": len(self._entries),            "suppressions": self._suppressions,            "evictions": self._evictions,            "deliveries_last_minute": len(self._deliveries),        }class RichConsoleNotifier(RecommendationNotifier):    """High-contrast terminal renderer.    Visual hierarchy is a safety feature, not decoration. Actionable bets get a    bordered green panel because they demand a decision. Refusals get one    compact dim table because they are diagnostics, and giving them equal    weight is the fastest route to alert fatigue.    Console writes are serialised behind an ``asyncio.Lock``. ``rich`` is not    reentrant, and two concurrent panels interleave into unreadable output.    """    __slots__ = ("_console", "_lock", "_rejection_rollup", "_started")    def __init__(        self,        debouncer: NotificationDebouncer | None = None,        *,        console: Console | None = None,    ) -> None:        super().__init__(NotificationChannel.CONSOLE, debouncer or AntiSpamRegistry())        self._console = console or Console(file=sys.stdout, highlight=False, soft_wrap=False)        self._lock = asyncio.Lock()        self._started = False        self._rejection_rollup: dict[str, int] = {}    async def start(self) -> None:        """Print the banner once. Idempotent."""        async with self._lock:            if self._started:                return            self._started = True            self._console.print()            self._console.rule(                "[bold cyan]BetDoc Advisor[/bold cyan] [dim]risk firewall active[/dim]",                style="cyan",            )            _log.info("console_notifier.started")    async def close(self) -> None:        """Tear down safely. Must survive being called twice or after a fault.        Flushing explicitly matters: a hard exit can otherwise truncate the        final panel mid-write and leave the terminal in a mangled state.        """        async with self._lock:            if not self._started:                return            self._started = False            with contextlib.suppress(Exception):                if self._rejection_rollup:                    self._console.print(                        Text(                            "Session rejection totals: "                            + ", ".join(                                f"{reason} x{count}"                                for reason, count in sorted(                                    self._rejection_rollup.items(),                                    key=lambda item: -item[1],                                )                            ),                            style="dim",                        )                    )                self._console.rule("[bold cyan]Advisor stopped[/bold cyan]", style="cyan")                self._console.show_cursor(True)                self._console.file.flush()            _log.info("console_notifier.closed")    async def notify_recommendation(        self, recommendation: TwinRecommendation, *, now: datetime | None = None    ) -> DebounceDecision:        """Render one actionable bet as a green panel, subject to debouncing."""        decision = self._debouncer.evaluate(recommendation, now=now)        if not decision.allow:            _log.debug(                "console_notifier.suppressed",                dedupe_key=decision.dedupe_key,                reason=decision.reason.value,                detail=decision.detail,            )            return decision        try:            async with self._lock:                self._console.print(self._render_panel(recommendation, decision))        except asyncio.CancelledError:            raise        except Exception as exc:            msg = f"console render failed: {exc!r}"            raise NotifierUnavailableError(msg, channel=self.channel.value) from exc        self._debouncer.record_delivery(recommendation, now=now)        return decision    async def notify_rejections(        self,        rejections: Sequence[TwinRecommendation],        *,        now: datetime | None = None,    ) -> int:        """Render refusals as one compact, muted table.        Batched into a single table rather than one alert each. Critical        refusals still pass through the debouncer's override, so a halted        session is never buried in the rollup.        """        if not rejections:            return 0        shown: list[TwinRecommendation] = []        for rejection in rejections:            reason = rejection.rejection_reason            if reason is not None:                self._rejection_rollup[reason.value] = (                    self._rejection_rollup.get(reason.value, 0) + 1                )            decision = self._debouncer.evaluate(rejection, now=now)            if decision.allow:                shown.append(rejection)                self._debouncer.record_delivery(rejection, now=now)        if not shown:            return 0        try:            async with self._lock:                self._console.print(self._render_rejection_table(shown))        except asyncio.CancelledError:            raise        except Exception as exc:            msg = f"console render failed: {exc!r}"            raise NotifierUnavailableError(msg, channel=self.channel.value) from exc        return len(shown)    async def notify_forecast(        self, forecast: SessionForecast, *, now: datetime | None = None    ) -> None:        """Render the session stance as a single status line plus warnings."""        try:            async with self._lock:                self._console.print(self._render_forecast(forecast))                for warning in forecast.warnings:                    self._console.print(Text(f"  ! {warning}", style="yellow"))        except asyncio.CancelledError:            raise        except Exception as exc:            msg = f"console render failed: {exc!r}"            raise NotifierUnavailableError(msg, channel=self.channel.value) from exc    # ------------------------------ rendering ----------------------------- #    def _render_panel(        self, recommendation: TwinRecommendation, decision: DebounceDecision    ) -> Panel:        """Green bordered panel: bookmaker, market, edge, stake, and the maths."""        edge = _edge_per_unit(recommendation) or 0.0        table = Table(box=None, show_header=False, pad_edge=False, expand=True)        table.add_column(style="bold white", no_wrap=True, width=18)        table.add_column(style="bright_white", overflow="fold")        table.add_row(            "Bookmaker",            recommendation.bookmaker.value.upper() if recommendation.bookmaker else "unknown",        )        table.add_row("Selection", recommendation.selection_label or "unknown")        table.add_row(            "Sport",            recommendation.sport_type.value if recommendation.sport_type else "unknown",        )        table.add_row("Target odds", f"{recommendation.target_odds:.3f}")        table.add_row("Edge", f"[bold green]{edge:+.2%}[/bold green] per unit staked")        table.add_row(            "Suggested stake",            f"[bold green]{format_inr(recommendation.suggested_stake_paise)}[/bold green]",        )        table.add_row("Expected value", format_inr(recommendation.expected_value_paise))        table.add_row(            "Kelly",            f"full {recommendation.full_kelly_fraction:.4f} "            f"-> authorised {recommendation.final_kelly_fraction:.4f}",        )        if recommendation.applied_uncertainty_penalty > 1.0:            table.add_row(                "News penalty",                f"[yellow]{recommendation.applied_uncertainty_penalty:.2f}x variance, "                f"{recommendation.stake_reduction_from_news:.0%} of stake withheld[/yellow]",            )        table.add_row("Binding limit", recommendation.binding_constraint or "none")        table.add_row("Valid until", recommendation.expires_at.strftime("%H:%M:%S UTC"))        table.add_row("Rationale", recommendation.justification_string)        table.add_row(            "Alert trigger",            f"[dim]{decision.reason.value}: {decision.detail}[/dim]",        )        title = f"[bold green]ACTIONABLE {recommendation.action_type.value.upper()}[/bold green]"        return Panel(            table,            title=title,            subtitle=f"[dim]trace {recommendation.trace_id[:12]}[/dim]",            border_style="green",            box=box.HEAVY,            padding=(0, 1),        )    def _render_rejection_table(self, rejections: Sequence[TwinRecommendation]) -> Table:        """Compact dim table: bookmaker, market, edge, stake, firewall reason."""        table = Table(            box=box.SIMPLE,            show_edge=False,            pad_edge=False,            title="[dim]firewall rejections[/dim]",            title_justify="left",            style="dim",        )        table.add_column("Book", style="grey62", no_wrap=True, max_width=10)        table.add_column("Market", style="grey62", overflow="ellipsis", max_width=28)        table.add_column("Edge", style="grey62", justify="right", no_wrap=True)        table.add_column("Stake", style="grey62", justify="right", no_wrap=True)        table.add_column("Firewall reason", style="red3", overflow="ellipsis")        for rejection in rejections:            edge = _edge_per_unit(rejection)            reason = rejection.rejection_reason            reason_text = reason.value if reason is not None else "unspecified"            style = (                "bold red" if reason is not None and reason.is_hard_capital_constraint else "red3"            )            table.add_row(                rejection.bookmaker.value if rejection.bookmaker else "-",                rejection.selection_label or "-",                f"{edge:+.2%}" if edge is not None else "-",                format_inr(rejection.suggested_stake_paise),                Text(reason_text, style=style),            )        return table    def _render_forecast(self, forecast: SessionForecast) -> Text:        """One-line session stance, coloured by verdict severity."""        verdict_style = {            ForecastVerdict.OPTIMAL: "bold green",            ForecastVerdict.ACCEPTABLE: "green",            ForecastVerdict.CAUTION: "yellow",            ForecastVerdict.STAND_DOWN: "bold red",        }[forecast.verdict]        regime_style = {            VolatilityRegime.CALM: "green",            VolatilityRegime.NORMAL: "cyan",            VolatilityRegime.ELEVATED: "yellow",            VolatilityRegime.EXTREME: "bold red",        }[forecast.volatility_regime]        line = Text()        line.append(f"{forecast.verdict.value.upper():<12}", style=verdict_style)        line.append(            f"{forecast.recommendations_issued}/{forecast.opportunities_screened} cleared  ",            style="white",        )        line.append(f"vol={forecast.volatility_regime.value}  ", style=regime_style)        line.append(f"lambda_mean={forecast.mean_uncertainty_penalty:.2f}  ", style="grey62")        line.append(            f"stake={format_inr(forecast.total_recommended_stake_paise)}  ",            style="white",        )        line.append(            f"budget_left={format_inr(forecast.remaining_loss_budget_paise)}",            style="grey62",        )        return line